import std.io

pub type AppError = Failed(Int64, Int64) | Nope

fn classify(n: Int64) -> Result<Int64, AppError> {
    if n > 0 {
        return Ok(n)
    }
    if n == 0i64 {
        return Err(Nope)
    }
    return Err(Failed(1i64, 2i64))
}

pub fn main() effect io -> Result<(), AppError> {
    let a = classify(5i64)
    match a {
        Ok(v) => { io.println("ok ${v}") }
        Err(Failed(x, y)) => { io.println("failed ${x} ${y}") }
        Err(Nope) => { io.println("nope") }
    }
    let b = classify(0i64)
    match b {
        Ok(v) => { io.println("ok ${v}") }
        Err(e) => { match e {
            Failed(x, y) => { io.println("inner ${x} ${y}") }
            Nope => { io.println("inner nope") }
        } }
    }
    let c = classify(-3i64)
    match c {
        Ok(v) => { io.println("ok ${v}") }
        Err(_) => { io.println("wildcard") }
    }
    return Ok(())
}
